using RagnarokCompanion.Services;
using Xunit;
namespace RagnarokCompanion.Tests;
public sealed class RagnarokDescriptionTests {
 [Fact] public void ColorsDividersAndEscapesPreserveRealNumbersAndSymbols(){var raw="Descrição\\r\\n--------------------------\\n^0000ffFOR +1.^000000\\n^00ff00Resistência +3%; -5%; 0,01%; 1234.^000000\\nTipo: ^777777Cabeça^000000\nPeso: 10\u0001";var lines=RagnarokDescriptionFormatter.Format(raw);Assert.Contains(lines,l=>l.Divider);Assert.Contains(lines,l=>l.Heading&&l.Text=="Efeitos");Assert.Contains(lines,l=>l.Heading&&l.Text=="Equipamento");Assert.Contains(lines.SelectMany(l=>l.Parts),p=>p.Color=="#0000FF"&&p.Text=="FOR +1.");var plain=RagnarokDescriptionFormatter.PlainText(raw);Assert.DoesNotContain("^0000ff",plain);Assert.DoesNotContain("---",plain);Assert.DoesNotContain('\u0001',plain);Assert.Contains("+3%; -5%; 0,01%; 1234.",plain);Assert.Contains("Peso: 10",plain);}
 [Fact] public void Item2255UsesPortugueseSourceWithoutChangingRawDatabaseDescription(){var index=ItemFarmIndex.Shared;Assert.Equal("[Q] Asas de Demônio",index.Find(2255)!.Name);var raw=index.Description(2255);Assert.Contains("^0000ffFOR +1.",raw);var lines=RagnarokDescriptionFormatter.Format(raw);var plain=RagnarokDescriptionFormatter.PlainText(raw);Assert.Contains("FOR +1.",plain);Assert.Contains("Anjo +3%.",plain);Assert.Contains("DEF: 6 DEFM: 2",plain);Assert.Contains("Peso: 10",plain);Assert.Contains("Nível necessário: 1",plain);Assert.Contains("Todas, exceto Aprendizes",plain);Assert.DoesNotContain("^000000",plain);Assert.Equal(raw,index.Description(2255));Assert.Equal(2,lines.Count(l=>l.Divider));}
}
